// Socket.IO 클라이언트 모킹 라이브러리 (테스트용)
(function() {
    'use strict';
    
    // 간단한 Socket.IO 클라이언트 구현
    function SocketIO(url, options) {
        this.url = url;
        this.options = options || {};
        this.id = 'test-socket-' + Math.random().toString(36).substr(2, 9);
        this.connected = false;
        this.eventListeners = {};
        
        console.log('Socket.IO 클라이언트 생성됨:', this.id);
        
        // 자동 연결 시뮬레이션
        setTimeout(() => {
            this.connected = true;
            this.emit('connect');
            console.log('Socket.IO 연결 시뮬레이션 완료');
        }, 1000);
    }
    
    SocketIO.prototype.on = function(event, callback) {
        if (!this.eventListeners[event]) {
            this.eventListeners[event] = [];
        }
        this.eventListeners[event].push(callback);
        console.log(`이벤트 리스너 등록: ${event}`);
        return this;
    };
    
    SocketIO.prototype.emit = function(event, data) {
        console.log(`이벤트 전송: ${event}`, data);
        
        // 특정 이벤트에 대한 응답 시뮬레이션
        if (event === 'po:created') {
            setTimeout(() => {
                this.triggerEvent('po:created', {
                    id: Math.floor(Math.random() * 1000),
                    branch_id: 1,
                    brand_id: 1,
                    industry_id: 1,
                    status: 'requested',
                    timestamp: new Date().toISOString(),
                    test: true
                });
            }, 500);
        }
        
        return this;
    };
    
    SocketIO.prototype.triggerEvent = function(event, data) {
        if (this.eventListeners[event]) {
            this.eventListeners[event].forEach(callback => {
                try {
                    callback(data);
                } catch (error) {
                    console.error(`이벤트 콜백 실행 오류 (${event}):`, error);
                }
            });
        }
    };
    
    SocketIO.prototype.disconnect = function() {
        this.connected = false;
        this.emit('disconnect', 'manual');
        console.log('Socket.IO 연결 해제됨');
        return this;
    };
    
    // 전역 io 함수 생성
    window.io = function(url, options) {
        return new SocketIO(url, options);
    };
    
    // Socket.IO 버전 정보
    window.io.version = '4.7.2-mock';
    
    console.log('Socket.IO 모킹 라이브러리 로드 완료');
})();
